// Watermark-based fetch (spec Section 5) -- read the last date_received we
// successfully advanced past, or fall back to an initial lookback window on
// the very first run.
//
// Why a lookback window and not "since yesterday": the CFPB Consumer Complaint
// Database only publishes a complaint once the company has responded or 15
// calendar days have passed (spec Section 3b, the CFPB 15-day rule). A poll
// watermarked to "yesterday" would mostly return nothing. INITIAL_LOOKBACK_DAYS
// gives the first run a realistic chance of hits while still behaving like a
// genuine incremental poller from the second run onward.
const INITIAL_LOOKBACK_DAYS = 30;

const staticData = $getWorkflowStaticData('node');

let watermarkDate = staticData.lastWatermarkDate;
let isFirstRun = false;

if (!watermarkDate) {
  isFirstRun = true;
  const fallback = new Date();
  fallback.setUTCDate(fallback.getUTCDate() - INITIAL_LOOKBACK_DAYS);
  watermarkDate = fallback.toISOString().slice(0, 10); // YYYY-MM-DD
}

return [
  {
    json: {
      watermarkDate,
      isFirstRun,
    },
  },
];

// Cap to 25/run (spec Section 5 -- cost predictability, not a rate-limit
// necessity; size=25 is already set on the request, this is a defensive
// second cap), flatten each ES hit down to the fields the rest of the
// pipeline needs (spec Section 3a), and advance the watermark to the latest
// date_received actually seen in this batch.
//
// Watermark precision note: CFPB's date_received_min filter is date-level
// (YYYY-MM-DD), not timestamp-level -- confirmed live during Phase 1 build
// (a sub-day timestamp is rejected by the API). That means a same-day poll
// can re-return complaints already fetched earlier that day. This workflow
// does not dedup here by design -- spec Section 11 assigns dedup to the
// storage layer ("Google Sheets Append-or-Update, dedup via complaint ID"),
// wired in a later phase. Downstream nodes must not assume every item here
// is new.
const MAX_PER_RUN = 25;

const response = $input.first().json;
const hits = (response.hits && response.hits.hits) || [];
const capped = hits.slice(0, MAX_PER_RUN);

const staticData = $getWorkflowStaticData('node');
let maxDate = staticData.lastWatermarkDate || null;

const out = capped.map((hit) => {
  const src = hit._source;
  const received = (src.date_received || '').slice(0, 10);
  if (received && (!maxDate || received > maxDate)) {
    maxDate = received;
  }
  return {
    json: {
      complaint_id: src.complaint_id,
      product: src.product,
      sub_product: src.sub_product,
      issue: src.issue,
      sub_issue: src.sub_issue,
      company: src.company,
      state: src.state,
      tags: src.tags,
      date_received: src.date_received,
      timely: src.timely,
      company_response: src.company_response,
      complaint_what_happened: src.complaint_what_happened,
    },
  };
});

if (maxDate) {
  staticData.lastWatermarkDate = maxDate;
}

return out;
